import {hashInputPackage} from './workspace.mjs';
import {researchSha256} from './research.mjs';
const clone=structuredClone;
const rowPayloads=rows=>rows.map(({rowHash,...value})=>value);
/** Equal-weighted daily closing observations; cash before the first decision is
 * recorded separately, and the closing mark of the final execution day is included. */
export function derivePortfolioSimulationMetrics({curve=[],decisions=[],evaluations=[]}={}){
 const points=[...curve].sort((a,b)=>a.sequence-b.sequence),exposures=points.map(p=>p.equity>0?Math.max(0,Math.min(1,1-p.cash/p.equity)):0),allocations=decisions.flatMap(d=>d.allocations??[]),scheduled=new Set(evaluations.filter(e=>e.graphEvaluation?.trace?.some(t=>t.type==='REBALANCE'&&['REBALANCE_DUE','WEIGHT_DIFFERENCE_BELOW_MINIMUM'].includes(t.reason))).map(e=>e.sequence)),actual=new Set(decisions.filter(d=>d.allocations?.some(a=>a.status==='FILLED')).map(d=>d.sequence));
 return {averageExposure:exposures.length?exposures.reduce((a,b)=>a+b,0)/exposures.length:null,maximumExposure:exposures.length?Math.max(...exposures):null,inMarketRatio:exposures.length?exposures.filter(v=>v>0).length/exposures.length:null,scheduledEvaluationCount:scheduled.size,actualRebalanceCount:actual.size,targetOrderCount:allocations.length,filledOrderCount:allocations.filter(a=>a.status==='FILLED').length,blockedOrderCount:allocations.filter(a=>a.status==='BLOCKED').length,minimumOrderBlockedCount:allocations.filter(a=>a.reason==='BELOW_MINIMUM_ORDER').length,noOrderCount:allocations.filter(a=>a.status==='HOLD').length,exposureBasis:{contractVersion:'DAILY_CLOSE_EXPOSURE_V1',weighting:'ONE_OBSERVATION_PER_COMPLETED_DAILY_FRAME',initialExposure:0,initialCashObservationIncluded:false,endBoundary:'FINAL_EXECUTION_DAY_CLOSE_INCLUDED',firstAt:points[0]?.asOf??null,lastAt:points.at(-1)?.asOf??null,observations:points.length,staleObservationCount:points.filter(p=>p.staleValuationInstrumentIds?.length).length},derivedFrom:{contractVersion:'PORTFOLIO_REPORT_ROW_PROJECTION_V1',curveHash:hashInputPackage(rowPayloads(curve)),decisionsHash:hashInputPackage(rowPayloads(decisions)),evaluationsHash:hashInputPackage(rowPayloads(evaluations))}};
}
export function portfolioEvaluationRows(rawRows){const groups=new Map();for(const row of rawRows)if(row.phase==='PROVIDER_RESULT'&&row.frameSequence){const key=row.frameSequence;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(row);}const result=[];for(const [sequence,parts]of groups){parts.sort((a,b)=>a.index-b.index);const text=parts.map(p=>p.text).join('');if(parts.length!==parts[0].partCount||parts.some((p,i)=>p.index!==i||p.partCount!==parts[0].partCount||p.sha256!==parts[0].sha256)||researchSha256(text)!==parts[0].sha256)throw Object.assign(new Error('결정 프레임의 보관 원문을 확인하세요.'),{code:'PORTFOLIO_REPORT_EVIDENCE'});const raw=JSON.parse(text);if(raw.contractVersion==='PORTFOLIO_FRAME_EVIDENCE_V1')result.push({sequence,graphEvaluation:clone(raw.graphEvaluation??raw.strategyEvaluation?.graphEvaluation)});}return result.sort((a,b)=>a.sequence-b.sequence);}
